mapper.select:
select * from lab_consumable where deleted = 0
and lab_id = #{labId}
and consumable_name like concat('%', #{consumableName}, '%')
and consumable_code like concat('%', #{consumableCode}, '%')
order by id desc limit #{offset}, #{pageSize}

mapper.update:
